SELECT bkt, COUNT(*) n, LISTAGG(r,'~') WITHIN GROUP (ORDER BY r) r FROM (SELECT MOD(ROWNUM,60) bkt, t.VOUCHER_NO||'|'||TO_CHAR(t.VM_DATE,'YYYY-MM-DD')||'|'||t.DR_AMOUNT||'|'||t.CR_AMOUNT||'|'||SUBSTR(TRIM(TRANSLATE(t.DESCRIPTION,'|~'||CHR(10)||CHR(13)||CHR(9),'     ')),1,80)||'|'||t.STATUS r FROM {P}GL_TRANSACTIONS_DETAILS t WHERE t.STATUS<>'C' AND t.ACCOUNT_NO='1263000' AND t.VM_DATE>=DATE '2023-01-01' AND (t.DESCRIPTION LIKE '%محروقات%' OR t.DESCRIPTION LIKE '%زيت%' OR t.DESCRIPTION LIKE '%سياره%' OR t.DESCRIPTION LIKE '%منزل%' OR t.DESCRIPTION LIKE '%سيارات%' OR t.DESCRIPTION LIKE '%ضيافة%' OR t.DESCRIPTION LIKE '%شاي%' OR t.DESCRIPTION LIKE '%سكر%' OR t.DESCRIPTION LIKE '%قهوة%' OR t.DESCRIPTION LIKE '%قهوه%' OR t.DESCRIPTION LIKE '%سكن%' OR t.DESCRIPTION LIKE '%افطار%' OR t.DESCRIPTION LIKE '%إفطار%' OR t.DESCRIPTION LIKE '%غداء%' OR t.DESCRIPTION LIKE '%غدا%' OR t.DESCRIPTION LIKE '%اكل%')) GROUP BY bkt